#define main legacy_main
#include "../pitch-cuda/main.cu"
#undef main
#include <vector>
#include <string>
#include <cmath>
#include <dlfcn.h>
constexpr float GUARD=-123.25f;constexpr int STEPS=3;
struct Fixture{int w,h,d;bool dim3;size_t stride,physical;float *pitched,*simple;cudaPitchedPtr descriptor{};std::vector<float>logical,initial;std::vector<double>goldlogical,goldphysical;std::vector<bool>valid;Fixture(int W,int H,int D,bool is3):w(W),h(H),d(D),dim3(is3){size_t pitch;if(dim3){cudaMalloc3D(&descriptor,make_cudaExtent(w*4,h,d));pitched=(float*)descriptor.ptr;pitch=descriptor.pitch;if(descriptor.ysize!=h)abort();}else cudaMallocPitch((void**)&pitched,&pitch,w*4,h);stride=pitch/4;physical=stride*h*d;cudaMalloc(&simple,w*h*d*4);logical.resize(w*h*d);initial.assign(physical,GUARD);goldlogical.resize(logical.size());goldphysical.assign(physical,GUARD);valid.assign(physical,false);for(size_t i=0;i<logical.size();i++){logical[i]=i%11==0?-80.f:i%11==1?80.f:i%11==2?-0.f:float(int((i*37)%513)-256)/16.f;double v=logical[i];for(int j=0;j<STEPS;j++)v=1./(1.+exp(-v));goldlogical[i]=v;}for(int z=0;z<d;z++)for(int y=0;y<h;y++)for(int x=0;x<w;x++){size_t li=(z*h+y)*w+x,pi=(z*h+y)*stride+x;initial[pi]=logical[li];goldphysical[pi]=goldlogical[li];valid[pi]=true;}}void reset(int mode){cudaMemcpy(mode==0?pitched:simple,mode==0?initial.data():logical.data(),(mode==0?physical:logical.size())*4,cudaMemcpyHostToDevice);}void launch(int mode){if(dim3){dim3 block(16,8,4),grid((w+15)/16,(h+7)/8,(d+3)/4);if(mode==0)parallelPitched3DAccess<<<grid,block>>>(descriptor,w,h,d);else parallelSimple3DAccess<<<grid,block>>>(simple,w,h,d);}else{dim3 block(16,16),grid((w+15)/16,(h+15)/16);if(mode==0)parallelPitched2DAccess<<<grid,block>>>(pitched,stride*4,w,h);else parallelSimple2DAccess<<<grid,block>>>(simple,w,h);}}};
int main(int argc,char**argv){int rep=argc>1?atoi(argv[1]):5;std::vector<Fixture>fs;fs.emplace_back(227,37,1,false);fs.emplace_back(256,33,1,false);fs.emplace_back(35,19,5,true);fs.emplace_back(64,17,3,true);int version;cudaRuntimeGetVersion(&version);Dl_info info;dladdr((void*)cudaMallocPitch,&info);printf("ACTUAL_CUDART version=%d path=%s\n",version,info.dli_fname);std::vector<float>prefix;for(auto&f:fs){float head[]={float(f.w),float(f.h),float(f.d),float(f.dim3),float(STEPS),float(f.stride),float(f.physical),GUARD};prefix.insert(prefix.end(),head,head+8);prefix.insert(prefix.end(),f.logical.begin(),f.logical.end());for(int mode=0;mode<2;mode++){f.reset(mode);f.launch(mode);}}cudaDeviceSynchronize();for(int trial=1;trial<=5;trial++){double times[8]={0};for(int z=0;z<rep;z++)for(int i=0;i<4;i++)for(int mode=0;mode<2;mode++){auto&f=fs[i];f.reset(mode);cudaDeviceSynchronize();auto st=std::chrono::steady_clock::now();for(int step=0;step<STEPS;step++)f.launch(mode);cudaDeviceSynchronize();times[2*i+mode]+=std::chrono::duration<double>(std::chrono::steady_clock::now()-st).count()/rep;}bool ok=cudaGetLastError()==cudaSuccess;double ma=0,mr=0,elapsed=0;size_t guards=0;std::vector<float>got;for(auto&f:fs)for(int mode=0;mode<2;mode++){auto&gold=mode==0?f.goldphysical:f.goldlogical;std::vector<float>a(gold.size());cudaMemcpy(a.data(),mode==0?f.pitched:f.simple,a.size()*4,cudaMemcpyDeviceToHost);for(size_t i=0;i<a.size();i++){if(mode==0&&!f.valid[i]){guards++;ok&=a[i]==GUARD;}else{double err=fabs(double(a[i])-gold[i]);ma=std::max(ma,err);mr=std::max(mr,err/std::max(fabs(gold[i]),1e-30));ok&=std::isfinite(a[i])&&err<=2e-6+2e-6*fabs(gold[i]);}}got.insert(got.end(),a.begin(),a.end());}auto art=prefix;art.insert(art.end(),got.begin(),got.end());const char*dir=getenv("STUDY_OUTPUT_DIR");std::string path=std::string(dir?dir:".")+"/output_trial"+std::to_string(trial)+".bin";FILE*fp=fopen(path.c_str(),"wb");fwrite(art.data(),4,art.size(),fp);fclose(fp);for(double t:times)elapsed+=t;printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.17g,\"max_rel_error\":%.17g,\"padding_guard_count\":%zu,\"timing_region\":\"sum8paths_3sigmoidsteps_kernelonly_resetexcluded\",\"jit_excluded\":true,\"internal_repeats\":%d,\"per_path_times_seconds\":[",trial,elapsed,ok?"true":"false",got.size(),ma,mr,guards,rep);for(int i=0;i<8;i++)printf(i?",%.17g":"%.17g",times[i]);printf("],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",path.c_str(),art.size());if(!ok)return 2;}for(auto&f:fs){cudaFree(f.pitched);cudaFree(f.simple);}}
